package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"regexp"
	"sort"
	"strings"
	"time"
	"unicode/utf8"
)

// environmentLimit caps resolver output; credentials are small.
const environmentLimit = 1 << 20

// projectMarkerVar names the controller's own marker exported with the environment.
const projectMarkerVar = "LIMA_DEBIAN_CTL_PROJECT"

var envName = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

// reservedEnvNames would change how the loader shells themselves behave or are
// read-only in bash/zsh; exporting them from the generated file is refused.
var reservedEnvNames = map[string]bool{
	"HOME": true, "BASH_ENV": true, "ENV": true, "ZDOTDIR": true, "IFS": true,
	"SHELLOPTS": true, "BASHOPTS": true, "UID": true, "EUID": true, "PPID": true,
	"BASH_VERSINFO": true, "status": true, "pipestatus": true,
}

// parseEnvironment reads literal KEY=value records separated by CR, LF or
// CRLF. Blank lines, "#" comments and an "export " prefix are accepted so
// ordinary .env files work, and a repeated name takes its last value.
// Values are taken verbatim, quotes included.
// Errors report line numbers only, never record contents.
func parseEnvironment(text string) (map[string]string, error) {
	if len(text) > environmentLimit || !utf8.ValidString(text) || strings.ContainsRune(text, 0) {
		return nil, errors.New("resolver output must be UTF-8, NUL-free, and at most 1 MiB")
	}
	normalized := strings.NewReplacer("\r\n", "\n", "\r", "\n").Replace(text)
	env := make(map[string]string)
	for i, line := range strings.Split(normalized, "\n") {
		if trimmed := strings.TrimSpace(line); trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		key, val, ok := strings.Cut(strings.TrimPrefix(line, "export "), "=")
		switch {
		case !ok || !envName.MatchString(key):
			return nil, fmt.Errorf("invalid environment record on line %d", i+1)
		case strings.HasPrefix(key, "LIMA_DEBIAN_CTL_") || reservedEnvNames[key]:
			return nil, fmt.Errorf("reserved environment name on line %d", i+1)
		}
		env[key] = val // repeated names: last definition wins, as in .env files
	}
	return env, nil
}

// shellQuote single-quotes s for POSIX shells; the result is always literal.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'"'"'`) + "'"
}

// renderEnvironment produces the guest environment file: sorted exports plus
// the project marker that readiness checks and exec verify against.
func renderEnvironment(env map[string]string, project string) string {
	keys := make([]string, 0, len(env))
	for key := range env {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	var b strings.Builder
	b.WriteString("# Generated by lima-debian-ctl. Do not edit.\n")
	for _, key := range keys {
		fmt.Fprintf(&b, "export %s=%s\n", key, shellQuote(env[key]))
	}
	fmt.Fprintf(&b, "export %s=%s\n", projectMarkerVar, shellQuote(project))
	return b.String()
}

// payload is what gets uploaded to the guest: the environment file and a
// non-secret banner describing the session.
type payload struct {
	Environment string // shell exports; contains the secret values
	MOTD        string // shown by `shell`; names only, never values
}

// resolveEnvironment runs the project's resolver on the host and renders its
// output. Resolver stdout/stderr are withheld from errors.
func resolveEnvironment(ctx context.Context, r Runner, c Config) (payload, error) {
	env := map[string]string{}
	if resolver := c.Environment.Resolver; len(resolver) > 0 {
		ctx, cancel := context.WithTimeout(ctx, c.resolverTimeout())
		defer cancel()
		text, err := run(ctx, r, Command{Name: resolver[0], Args: resolver[1:], Dir: c.Root, Limit: environmentLimit})
		if err != nil {
			return payload{}, fmt.Errorf("credential resolver failed (output withheld): %w", err)
		}
		if env, err = parseEnvironment(text); err != nil {
			return payload{}, err
		}
	}
	return payload{Environment: renderEnvironment(env, c.Project), MOTD: renderMOTD(c, env)}, nil
}

// renderMOTD builds the banner printed by `lima-debian-ctl shell`: one item
// per line under an aligned label column. Colors are ANSI, disabled when
// NO_COLOR is set on the host at render time.
func renderMOTD(c Config, env map[string]string) string {
	keys := make([]string, 0, len(env))
	for key := range env {
		keys = append(keys, key)
	}
	sort.Strings(keys)

	bold, cyan, dim, reset := "\x1b[1m", "\x1b[36m", "\x1b[2m", "\x1b[0m"
	if _, noColor := os.LookupEnv("NO_COLOR"); noColor {
		bold, cyan, dim, reset = "", "", "", ""
	}
	var b strings.Builder
	row := func(label string, values ...string) {
		for i, v := range values {
			if i == 0 {
				fmt.Fprintf(&b, "%s%-9s%s %s\n", bold, label, reset, v)
			} else {
				fmt.Fprintf(&b, "%-9s %s\n", "", v)
			}
		}
	}
	b.WriteString("\n")
	row("Project", cyan+c.Project+reset)
	row("VM", c.Instance)
	row("Activated", time.Now().Format("2006-01-02 15:04"))
	mounts := make([]string, len(c.Mounts))
	for i, m := range c.Mounts {
		mode := "rw"
		if !m.Writable {
			mode = "ro"
		}
		mounts[i] = fmt.Sprintf("%s %s<- %s (%s)%s", m.Guest, dim, m.Host, mode, reset)
	}
	row("Mount", mounts...)
	if len(c.Forwards) > 0 {
		fwd := make([]string, len(c.Forwards))
		for i, f := range c.Forwards {
			if f.Direction == GuestToHost {
				fwd[i] = fmt.Sprintf("guest:%d -> host %s:%d", f.ListenPort, f.TargetHost, f.TargetPort)
			} else {
				fwd[i] = fmt.Sprintf("host:%d -> guest %s:%d", f.ListenPort, f.TargetHost, f.TargetPort)
			}
		}
		row("Forward", fwd...)
	}
	if len(keys) > 0 {
		row("Env", keys...)
	} else {
		row("Env", dim+"(none)"+reset)
	}
	if c.forwardAgent() {
		row("SSH agent", "forwarded from host "+dim+"(/run/host-services/ssh-auth.sock)"+reset)
	} else {
		row("SSH agent", dim+"off (forward_agent = false)"+reset)
	}
	row("Refresh", dim+"lima-debian-ctl provision"+reset)
	b.WriteString("\n")
	return b.String()
}
